-- GhostTab schema. Run this migration in a Supabase project before using production mode.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.collections (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(name) between 1 and 100), description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,name));
create table public.bookmarks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, url text not null, title text not null, domain text not null, favicon_url text, reason text not null, description text, collection_id uuid references public.collections(id) on delete set null, status text not null default 'active' check(status in ('active','archived')), saved_at timestamptz not null default now(), last_visited_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tags (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, created_at timestamptz not null default now(), unique(user_id,name));
create table public.bookmark_tags (bookmark_id uuid not null references public.bookmarks(id) on delete cascade, tag_id uuid not null references public.tags(id) on delete cascade, primary key(bookmark_id,tag_id));
create table public.bookmark_activity (id uuid primary key default gen_random_uuid(), bookmark_id uuid not null references public.bookmarks(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, activity_type text not null check(activity_type in ('saved','opened','edited','archived','restored','tagged','moved')), created_at timestamptz not null default now());
create table public.reminders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, bookmark_id uuid not null references public.bookmarks(id) on delete cascade, remind_at timestamptz not null, status text not null default 'pending' check(status in ('pending','completed','dismissed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end;$$;
create trigger touch_profiles before update on public.profiles for each row execute procedure public.touch_updated_at(); create trigger touch_collections before update on public.collections for each row execute procedure public.touch_updated_at(); create trigger touch_bookmarks before update on public.bookmarks for each row execute procedure public.touch_updated_at(); create trigger touch_reminders before update on public.reminders for each row execute procedure public.touch_updated_at();
alter table public.profiles enable row level security; alter table public.collections enable row level security; alter table public.bookmarks enable row level security; alter table public.tags enable row level security; alter table public.bookmark_tags enable row level security; alter table public.bookmark_activity enable row level security; alter table public.reminders enable row level security;
create policy "profiles private" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid()); create policy "collections private" on public.collections for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "bookmarks private" on public.bookmarks for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "tags private" on public.tags for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "bookmark tags scoped" on public.bookmark_tags for all using (exists(select 1 from public.bookmarks b where b.id=bookmark_id and b.user_id=auth.uid()) and exists(select 1 from public.tags t where t.id=tag_id and t.user_id=auth.uid())) with check (exists(select 1 from public.bookmarks b where b.id=bookmark_id and b.user_id=auth.uid()) and exists(select 1 from public.tags t where t.id=tag_id and t.user_id=auth.uid()));
create policy "activity private" on public.bookmark_activity for all using (user_id=auth.uid()) with check (user_id=auth.uid() and exists(select 1 from public.bookmarks b where b.id=bookmark_id and b.user_id=auth.uid())); create policy "reminders private" on public.reminders for all using (user_id=auth.uid()) with check (user_id=auth.uid() and exists(select 1 from public.bookmarks b where b.id=bookmark_id and b.user_id=auth.uid()));
create index bookmarks_owner_activity on public.bookmarks(user_id,status,last_visited_at); create index activity_bookmark_created on public.bookmark_activity(bookmark_id,created_at desc); create index reminders_owner_due on public.reminders(user_id,status,remind_at);
